//! The file: two passes of the emitter, the first to find the references that close cycles,
//! the second to print with them boxed; then the header, the items in order, and the helpers
//! the items used.

use crate::cycles::on_cycle;
use crate::emit::{Emitter, Plan};
use flowapi::Program;

const HEADER: &str =
    "// Generated by flowapi from an API description. Do not edit: generate again.\n";

const NEVER: &str = "\
/// No value: what a schema allows none of. It deserializes nothing.
#[derive(Debug, Clone, PartialEq)]
pub enum Never {}

impl Serialize for Never {
    fn serialize<S: serde::Serializer>(&self, _: S) -> Result<S::Ok, S::Error> {
        match *self {}
    }
}

impl<'de> Deserialize<'de> for Never {
    fn deserialize<D: serde::Deserializer<'de>>(_: D) -> Result<Self, D::Error> {
        Err(serde::de::Error::custom(\"no value is allowed here\"))
    }
}
";

const INTEGER: &str = "\
/// A JSON integer: any number with no fraction, `1.0` among them, kept as an `i64`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Default)]
pub struct Integer(pub i64);

impl From<i64> for Integer {
    fn from(value: i64) -> Self {
        Self(value)
    }
}

impl From<Integer> for i64 {
    fn from(value: Integer) -> Self {
        value.0
    }
}

impl std::ops::Deref for Integer {
    type Target = i64;
    fn deref(&self) -> &i64 {
        &self.0
    }
}

impl Serialize for Integer {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_i64(self.0)
    }
}

impl<'de> Deserialize<'de> for Integer {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        struct Reader;
        impl serde::de::Visitor<'_> for Reader {
            type Value = Integer;
            fn expecting(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
                f.write_str(\"an integer\")
            }
            fn visit_i64<E: serde::de::Error>(self, v: i64) -> Result<Integer, E> {
                Ok(Integer(v))
            }
            fn visit_u64<E: serde::de::Error>(self, v: u64) -> Result<Integer, E> {
                i64::try_from(v).map(Integer).map_err(|_| E::custom(\"an integer past i64\"))
            }
            fn visit_f64<E: serde::de::Error>(self, v: f64) -> Result<Integer, E> {
                let whole = v.fract() == 0.0 && v >= -9_223_372_036_854_775_808.0 && v < 9_223_372_036_854_775_808.0;
                if whole { Ok(Integer(v as i64)) } else { Err(E::custom(\"a number with a fraction\")) }
            }
        }
        deserializer.deserialize_any(Reader)
    }
}
";

const SOME: &str = "\
/// A present field read as `Some`, `null` among its values: absent stays `None`.
fn deserialize_some<'de, D, T>(deserializer: D) -> Result<Option<T>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: Deserialize<'de>,
{
    T::deserialize(deserializer).map(Some)
}
";

pub(crate) fn program(p: &Program<'_>, sdk: bool) -> String {
    let reserved = if sdk {
        crate::RESERVED_SDK
    } else {
        crate::RESERVED
    };
    let mut first = Emitter::new(p, Plan::default(), reserved);
    first.run();
    let n = first.items.len();
    let direct: Vec<(usize, usize)> = first
        .edges
        .iter()
        .filter(|e| e.2)
        .map(|e| (e.0, e.1))
        .collect();
    let is_alias = |i: usize| first.items.get(i).is_some_and(|it| it.alias);
    let aliases: Vec<(usize, usize)> = first
        .edges
        .iter()
        .filter(|e| is_alias(e.0) && is_alias(e.1))
        .map(|e| (e.0, e.1))
        .collect();
    let mut newtype: Vec<usize> = on_cycle(n, &aliases).into_iter().map(|e| e.0).collect();
    newtype.sort_unstable();
    newtype.dedup();
    let plan = Plan {
        boxed: on_cycle(n, &direct),
        newtype,
    };
    let mut second = Emitter::new(p, plan, reserved);
    let order = second.run();
    let mut out = String::with_capacity(4096 + n * 256);
    out.push_str(HEADER);
    out.push_str("\nuse serde::{Deserialize, Serialize};\n");
    if second.uses.map {
        out.push_str("use std::collections::BTreeMap;\n");
    }
    for i in order {
        if let Some(item) = second.items.get(i) {
            out.push('\n');
            out.push_str(&item.text);
        }
    }
    if second.uses.helpers.never {
        out.push('\n');
        out.push_str(NEVER);
    }
    if second.uses.helpers.some {
        out.push('\n');
        out.push_str(SOME);
    }
    if second.uses.helpers.integer {
        out.push('\n');
        out.push_str(INTEGER);
    }
    if sdk {
        crate::sdk::write(&mut second, &mut out);
    }
    out
}
